from pathlib import Path
import base64
import gzip
import json

OLD = "0.1.0-alpha.12.16"
NEW = "0.1.0-alpha.12.17"

RECENCY_B64 = """"""
TEST_B64 = """"""
CONTRACT_B64 = """"""


def decode_to(path: str, payload: str) -> None:
    Path(path).write_bytes(gzip.decompress(base64.b64decode(payload)))


decode_to("custom_components/dummy_os_data/recency_weighting.py", RECENCY_B64)
decode_to("tests/test_recency_weighting.py", TEST_B64)
decode_to("tests/test_recency_weighting_sensor_contract.py", CONTRACT_B64)

sensor = Path("custom_components/dummy_os_data/sensor.py")
text = sensor.read_text()
import_marker = "from .time_windows import calculate_time_windows\n"
assert import_marker in text
if "from .recency_weighting import calculate_recency_weighting" not in text:
    text = text.replace(import_marker, import_marker + "from .recency_weighting import calculate_recency_weighting\n", 1)
registration = "            DummyOSEnergyTimeWindowsSensor(coordinator),\n"
assert registration in text
if "DummyOSEnergyRecencyWeightingSensor(coordinator)" not in text:
    text = text.replace(registration, registration + "            DummyOSEnergyRecencyWeightingSensor(coordinator),\n", 1)
class_marker = "\n\nclass DummyOSEnergyPeakLearningSensor(DummyOSBaseSensor):"
assert class_marker in text
recency_class = '''\n\nclass DummyOSEnergyRecencyWeightingSensor(DummyOSBaseSensor):\n    \"\"\"Observer-only Step 8A Energy recency-weighting diagnostics.\"\"\"\n\n    _attr_name = \"DO Energy Recency Weighting\"\n    _attr_unique_id = \"do_energy_recency_weighting\"\n    _attr_suggested_object_id = \"do_energy_recency_weighting\"\n    _attr_icon = \"mdi:timeline-clock-outline\"\n    _unrecorded_attributes = frozenset({\"per_candidate_metrics\", \"segment_metrics\", \"early_late_metrics\"})\n\n    @property\n    def name(self) -> str:\n        \"\"\"Return the canonical runtime name used for friendly_name.\"\"\"\n        return \"DO Energy Recency Weighting\"\n\n    def _result(self) -> dict[str, Any]:\n        return calculate_recency_weighting(\n            self.coordinator.records,\n            self.coordinator.evaluations,\n            self.coordinator.profile,\n            dt_util.as_local,\n        )\n\n    @property\n    def native_value(self) -> str:\n        return str(self._result()[\"status\"])\n\n    @property\n    def extra_state_attributes(self) -> dict[str, Any]:\n        return dict(self._result())\n'''
if "class DummyOSEnergyRecencyWeightingSensor" not in text:
    text = text.replace(class_marker, recency_class + class_marker, 1)
sensor.write_text(text)

init = Path("custom_components/dummy_os_data/__init__.py")
text = init.read_text()
marker = '    ("sensor", "do_energy_time_windows", "sensor.do_energy_time_windows"),\n'
assert marker in text
if 'do_energy_recency_weighting", "sensor.do_energy_recency_weighting' not in text:
    text = text.replace(marker, marker + '    ("sensor", "do_energy_recency_weighting", "sensor.do_energy_recency_weighting"),\n', 1)
init.write_text(text)

migrations = Path("custom_components/dummy_os_data/entity_migrations.py")
text = migrations.read_text()
marker = '    "do_energy_time_windows": "sensor.dummy_os_forecast_do_energy_time_windows",\n'
assert marker in text
if '"do_energy_recency_weighting":' not in text:
    text = text.replace(marker, marker + '    "do_energy_recency_weighting": "sensor.dummy_os_forecast_do_energy_recency_weighting",\n', 1)
migrations.write_text(text)

const = Path("custom_components/dummy_os_data/const.py")
text = const.read_text()
assert f'VERSION = "{OLD}"' in text
const.write_text(text.replace(f'VERSION = "{OLD}"', f'VERSION = "{NEW}"', 1))

manifest = Path("custom_components/dummy_os_data/manifest.json")
data = json.loads(manifest.read_text())
assert data["version"] == OLD
data["version"] = NEW
manifest.write_text(json.dumps(data, indent=2) + "\n")

release_test = Path("tests/test_release_consistency.py")
text = release_test.read_text()
assert f'VERSION = "{OLD}"' in text
text = text.replace(f'VERSION = "{OLD}"', f'VERSION = "{NEW}"', 1)
energy_marker = '    "do_energy_time_windows",\n'
assert energy_marker in text
if '    "do_energy_recency_weighting",\n' not in text:
    text = text.replace(energy_marker, energy_marker + '    "do_energy_recency_weighting",\n', 1)
text = text.replace('self.assertEqual(20, sum(sensor_source.count(f\'_attr_unique_id = "{unique_id}"\') for unique_id in EXPECTED_ENERGY_IDS))', 'self.assertEqual(21, sum(sensor_source.count(f\'_attr_unique_id = "{unique_id}"\') for unique_id in EXPECTED_ENERGY_IDS))')
runtime_marker = '("DummyOSEnergyTimeWindowsSensor", "DO Energy Time Windows"),\n'
assert runtime_marker in text
if '("DummyOSEnergyRecencyWeightingSensor", "DO Energy Recency Weighting"),' not in text:
    text = text.replace(runtime_marker, runtime_marker + '            ("DummyOSEnergyRecencyWeightingSensor", "DO Energy Recency Weighting"),\n', 1)
release_test.write_text(text)

Path("RELEASE_NOTES.md").write_text('''# GitHub Release\n\n**Tag:** `0.1.0-alpha.12.17`  \n**Release title:** Dummy OS Forecast 0.1.0-alpha.12.17 - Energy Recency Weighting Observer\n\n## Dummy OS Forecast 0.1.0-alpha.12.17\n\nStap 8A voegt de observer-only Energy Recency Weighting-laag toe. De bestaande productieforecast blijft exact de huidige 28-daagse recency-half-life gebruiken.\n\n### Nieuw\n- `sensor.do_energy_recency_weighting` met schema `8a.1` en algoritme `recency_weighting_observer_v1`.\n- Forward-only replay van 14, 21, 28 en 42 dagen op exact dezelfde fallback- en samplebasis.\n- Control-reproductiegate tegen de opgeslagen 28-daagse productieforecast.\n- MAE, RMSE, bias, WMAPE, median, p90, paired win-rate, ESS, segment- en early/late-diagnostiek.\n- Conservatieve promotiediagnostiek; `promotion_ready` kan observer-only waar worden, maar forecastinvloed blijft uit.\n\n### Identity-gate\n- Canonical `entity_id`: `sensor.do_energy_recency_weighting`.\n- `unique_id` en `suggested_object_id`: `do_energy_recency_weighting`.\n- Runtime/friendly name: `DO Energy Recency Weighting`.\n- De mogelijke automatisch gegenereerde `sensor.dummy_os_forecast_do_energy_recency_weighting` is expliciet als veilige migratiealias vastgelegd.\n- Geen `_2`-variant of alias-sensor.\n\n### Ongewijzigd\n- Productie-half-life blijft exact 28 dagen.\n- `forecast.py` productiepad en confidenceformule blijven ongewijzigd.\n- Peak Learning, Time Windows, fallback-hiërarchie, Model Health en plannerfeed blijven ongewijzigd.\n- Native architectuur blijft exact 15 minuten / 72 uur / 288 slots.\n\n### Validatie\n- Volledige unit-/regressietestset.\n- Compile en manifestcontrole.\n- Identity/friendly-name release-gate.\n- Na installatie: live Home Assistant-validatie van status, control reproduction en observer-only flags.\n''')
